    for key, value in env_mapping.items():
        if env_prefix is not None and key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            env_config[env_key] = _coerce(value, defaults.get(env_key))
    config.update(env_config)
